window.VARDAM_DATA = {"characters":[{"id":1,"name":"Tessa Rook","gender":{"es":"mujer","en":"woman"},"age":20,"appearance":{"es":"Rizos cortos naranja cobrizo, ojos ámbar y pecas; gafas sobre el pelo, camisa marfil y azul, delantal cobrizo con emblema de yunque. Lleva una gran caldera de vidrio con fibras vivas luminosas rosa anaranjado, tuberías y fuelle. Caldera: líneas de soldadura.","en":"Short copper-orange curls, amber eyes and freckles; an anvil apron and a glass boiler filled with pink-orange living fibres."},"bio":{"es":"Directa y competitiva. Busca licencia para sostener el taller de Ors, su padre. Conoce a Grit; discute patentes con Neri.","en":"Direct, freckled and fiercely competitive. She wants a repair licence to keep her father's workshop alive, and has plenty to say about Neri's patents."},"rank":"I","branch":"Boiler","faction":"academy","role":{"es":"Aprendiz de forja","en":"Forge apprentice"}},{"id":2,"name":"Pru Sorel","gender":{"es":"mujer","en":"woman"},"age":21,"appearance":{"es":"Bob negro violáceo hasta la mandíbula y ojos gris verdoso. Mecanismo circular junto al oído unido a una pieza acústica que recorre un lateral de la mandíbula; cuello alto de láminas marfil y vidrio, ropa negra y verde seco, disco de resonancia. Eco: anillos de silencio.","en":"A black-violet jaw-length bob, a side-mounted acoustic mechanism, an ivory membrane collar and a resonance disc."},"bio":{"es":"Humor seco. Quiere diseñar escenarios acústicos; crea radioteatro con Maro y disputa decisiones creativas.","en":"A dry wit behind a porcelain sound collar. She dreams of building acoustic stages and makes radio plays with Maro, provided they can agree on who is directing."},"rank":"I","branch":"Echo","faction":"academy","role":{"es":"Diseñadora acústica","en":"Acoustic designer"}},{"id":3,"name":"Berta Noll","gender":{"es":"mujer","en":"woman"},"age":22,"appearance":{"es":"Trenza castaña larga, ojos ámbar, pecas y cuerpo alto y fuerte; pequeña placa de latón en la mejilla. Camisa mostaza y peto azul, con caja de cría transparente de marco dorado que contiene escarabajos y vegetación. Enjambre: escarabajos transportadores.","en":"A long brown braid, amber eyes and freckles; a brass cheek plate and a glass nursery full of beetles."},"bio":{"es":"Paciente y terca. Defiende tecnología rural; su hermana Vela eligió un contrato empresarial que las enfrenta.","en":"Patient, stubborn and proud of village technology. Her beetle carriers are useful long before a fight begins. Her sister Vela chose a very different path."},"rank":"I","branch":"Swarm","faction":"academy","role":{"es":"Inventora rural","en":"Rural inventor"}},{"id":4,"name":"Neri Voss","gender":{"es":"mujer","en":"woman"},"age":20,"appearance":{"es":"Bob corto ondulado plateado con matiz lila y ojos vino. Sastrería marfil y burdeos, armadura de porcelana y abanico articulado de grandes placas craqueladas con ligamentos vivos rojo oscuro. Bastion: hojas plegables.","en":"A short silver-lilac bob, wine-red eyes, ivory-and-burgundy tailoring and articulated porcelain plates with dark-red living ligaments."},"bio":{"es":"Disciplinada y mordaz. Quiere reconocimiento propio. Su madre Maud dirige Nueve Hornos; Neri desconoce gran parte de sus operaciones.","en":"Disciplined and sharp-tongued, Neri wants recognition for her own designs. Folding porcelain blades and burgundy tailoring are unmistakably hers."},"rank":"II","branch":"Bastion","faction":"academy","role":{"es":"Diseñadora de porcelana","en":"Porcelain designer"}},{"id":5,"name":"Odra Kelm","gender":{"es":"mujer","en":"woman"},"age":23,"appearance":{"es":"Piel oscura, cabello muy largo y ondulado verde mar y ojos dorados. Abrigo azul profundo de bordes dorados; grandes membranas rosa coral con silueta de aleta, manómetro y depósito de presión. Caldera: presión osmótica.","en":"Dark skin, long sea-green waves and golden eyes; blue-and-gold clothes and broad coral-pink ray-shaped membranes."},"bio":{"es":"Sociable y calculadora. Quiere reparar los faros de su isla; negocia con su tía Ysra.","en":"Sociable, calculating and determined to restore her island's beacons. Coral-pink membranes guide her pressure jets; her aunt Ysra knows the price of every voyage."},"rank":"II","branch":"Boiler","faction":"academy","role":{"es":"Aprendiz de navegación","en":"Navigation apprentice"}},{"id":6,"name":"Cira Fen","gender":{"es":"mujer","en":"woman"},"age":19,"appearance":{"es":"Piel morena, ojos ámbar y dos trenzas lavanda con engranajes y acopladores integrados en el trenzado. Capucha de pétalos ciruela y marfil, mangas de membrana luminosa y cámara de vidrio con polillas y cultivos rosados. Enjambre: polillas exploradoras.","en":"Brown skin and lavender braids with integrated gears; a plum petal hood and a translucent moth nursery."},"bio":{"es":"Reservada, observadora y rencorosa. Busca independencia de los criaderos baratos; comparte inventos con Edda y discuten su propiedad.","en":"Observant, reserved and slow to forgive. Lavender braids with integrated gears frame her moth nursery. She and Edda share inventions, but not always opinions about ownership."},"rank":"I","branch":"Swarm","faction":"academy","role":{"es":"Exploradora de criaderos","en":"Hatchery scout"}},{"id":7,"name":"Sava Renn","gender":{"es":"mujer","en":"woman"},"age":21,"appearance":{"es":"Trenza castaña baja y ojos verdes, normalmente cubiertos por gafas asimétricas de lentes ámbar. Camisa marfil, acentos de rescate rojos, lazo verde en forma de hojas y dispositivo de antebrazo con fibras vegetales tras vidrio. Trama: fibras de sutura.","en":"A low brown braid, asymmetric amber goggles, an ivory rescue outfit and a glass forearm device filled with living fibres."},"bio":{"es":"Amable y firme. Elige rescate y puede combatir mediante sujeción. Aprende de Nell y entrena con Bram.","en":"Kindness with a firm backbone. Living suture fibres can help the injured or restrain an opponent. She studies with Nell and practises coordinated rescues with Bram."},"rank":"I","branch":"Weave","faction":"academy","role":{"es":"Aprendiz de rescate","en":"Rescue apprentice"}},{"id":8,"name":"Dima Brack","gender":{"es":"mujer","en":"woman"},"age":22,"appearance":{"es":"Pelo rojo revuelto, ojos ámbar y gafas sobre la cabeza. Chaqueta roja y verde petróleo con arnés; brazo mecánico de piezas marfil y latón, tendones rojos y cartucho de presión de vidrio. Su presentación es atlética y andrógina; sigue siendo mujer. Caldera: bolsas retardadas.","en":"Tousled red hair and amber eyes; a red-and-teal jacket, harness and mechanical arm with red tendons and glass pressure cartridges."},"bio":{"es":"Apostadora e ingeniosa. Sueña con pirotecnia legal; tiene una deuda pequeña propia y una amistad leal con Ruf.","en":"Quick-witted, restless and fond of a wager. Her delayed pressure bags could become a legal fireworks business. Ruf is a real friend, not her keeper."},"rank":"I","branch":"Boiler","faction":"academy","role":{"es":"Inventora de pirotecnia","en":"Pyrotechnics inventor"}},{"id":9,"name":"Edda Vale","gender":{"es":"mujer","en":"woman"},"age":20,"appearance":{"es":"Rizos cortos rubio lino y ojos miel. Armazón externo de ventanillas sobre la cabeza, ropa marfil y petróleo con naranja, mochila de caparazón azul verdoso con frascos vegetales. Todo su equipo es externo y desmontable: no tiene implantes. Sin implantes; enjambre externo.","en":"Short flax-blonde curls, a folding-window head frame and a teal shell backpack. All equipment is external and detachable; she has no implants."},"bio":{"es":"Exigente y práctica. Diseña ayudas accesibles. Marga es su mentora; comparte proyectos con Cira e Ivo.","en":"Practical and exacting. All of her detachable equipment stays outside her body. She wants affordable assistive devices and learns repairable design from Marga."},"rank":"I","branch":"Swarm","faction":"academy","role":{"es":"Inventora de equipo externo","en":"External gear inventor"}},{"id":10,"name":"Yara Spint","gender":{"es":"mujer","en":"woman"},"age":21,"appearance":{"es":"Coleta alta muy larga dorada y castaña, ojos rojos, ropa de carreras azul y marfil con bordes de relámpago. Brazo mecanizado con tendones rojizos y cilindros bioeléctricos azules, conectado a equipo de velocidad. Impulso: salto acelerado.","en":"A long golden-brown high ponytail, red eyes, a blue-and-ivory racing outfit and a mechanical arm with red tendons and blue electrical cylinders."},"bio":{"es":"Alegre y temerosa de ser reemplazada. Persigue récords; su exceso de entrenamiento puede tener consecuencias.","en":"Bright, competitive and worried about being replaceable. She chases inter-academy records with a red-tendon electrical arm, but overtraining always has a cost."},"rank":"II","branch":"Impulse","faction":"academy","role":{"es":"Corredora de la academia","en":"Academy racer"}},{"id":11,"name":"Tamsin Bale","gender":{"es":"mujer","en":"woman"},"age":22,"appearance":{"es":"Cabello verde oscuro largo y ondulado, ojos dorados y gafas redondas. Prendas verdes, ciruela y marfil; hombreras de grandes hongos escalonados y membrana verde de nervaduras claras tensada entre varillas de latón. Trama: construcción fúngica.","en":"Long dark-green waves, round glasses, tiered mushroom shoulders and a translucent green membrane stretched between brass rods."},"bio":{"es":"Lenta para confiar y de humor seco. Quiere viviendas para damnificados; discute extracción de recursos con Berta.","en":"Slow to trust and armed with a very dry sense of humour. She grows structures for displaced communities and argues with Berta about responsible harvesting."},"rank":"II","branch":"Weave","faction":"academy","role":{"es":"Constructora de micelio","en":"Mycelium builder"}},{"id":12,"name":"Bram Mott","gender":{"es":"hombre","en":"man"},"age":22,"appearance":{"es":"Pelo negro corto y revuelto, ojos dorados y cuerpo ancho. Uniforme verde y marfil con arnés; hombros de placas cerámicas y gran escudo de paneles de puerta articulados, con bisagras doradas y nervaduras claras. Bastion: muros por capas.","en":"Short tousled black hair, golden eyes and a broad build; green-and-ivory clothes, ceramic shoulders and a large articulated door-panel shield."},"bio":{"es":"Nervioso y capaz. Aspira a rescate urbano; su madre Alda dirige el comedor.","en":"Nervous does not mean incapable. Behind a broad folding-door shield, Bram wants to become a city rescuer. Alda, who runs the canteen, is his mother."},"rank":"I","branch":"Bastion","faction":"academy","role":{"es":"Aprendiz de rescate urbano","en":"Urban rescue apprentice"}},{"id":13,"name":"Ivo Tarn","gender":{"es":"hombre","en":"man"},"age":20,"appearance":{"es":"Cabello gris claro revuelto y ojos azules. Capa índigo de bordes en zigzag, guantes aislantes y depósitos dorsales de vidrio con ramificaciones bioeléctricas azules. Tiene una pieza mecánica lateral en el cuello; conserva piel visible en el resto del cuello. Impulso: rutas conductoras.","en":"Tousled grey-white hair, blue eyes and a small lateral neck mechanism. An indigo angular cape frames blue branching electrical reservoirs."},"bio":{"es":"Sarcástico y curioso. Busca interfaces abiertas; disputa la autoría de proyectos con Edda.","en":"Sarcastic, curious and determined to build interfaces without corporate locks. Blue branching electricity fills his glass rig; he shares projects and authorship disputes with Edda."},"rank":"I","branch":"Impulse","faction":"academy","role":{"es":"Diseñador de interfaces","en":"Interface designer"}},{"id":14,"name":"Ruf Halden","gender":{"es":"hombre","en":"man"},"age":23,"appearance":{"es":"Pelo corto rojizo, cejas gruesas y cuerpo musculoso. Camisa marfil y arnés burdeos; arco dorsal con poleas y gruesas cuerdas blancas de tensión, que puede sujetar con ambas manos. Trama: tensión acumulada.","en":"Short auburn hair, thick eyebrows and a strong build; an arched dorsal pulley frame and thick white tension cords."},"bio":{"es":"Sereno y competitivo. Quiere abrir un gimnasio; cuida a Dima sin decidir por ella.","en":"Calm and competitive, with a pulley frame and heavy living cords. He dreams of opening a public gym and values Dima's friendship without making her choices for her."},"rank":"II","branch":"Weave","faction":"academy","role":{"es":"Luchador de tensión","en":"Tension fighter"}},{"id":15,"name":"Seth Orell","gender":{"es":"hombre","en":"man"},"age":21,"appearance":{"es":"Cabello negro recogido bajo y ojos dorados, pequeñas piezas doradas junto a la ceja y la sien. Abrigo violeta de paneles como plumas, arnés dorsal con cilindro bioeléctrico y conductores; guante de agujas finas. Impulso: agujas eléctricas.","en":"Black hair tied low, golden eyes, brass brow details, a violet feather-panel coat and a dorsal electrical cylinder with fine conductors."},"bio":{"es":"Formal y ambicioso. Busca financiación de frontera; envidia ventajas de Venn sin rendirse ante ellas.","en":"Formal, ambitious and quietly stubborn. Fine conductive needles and a violet dorsal cylinder support his training. He wants frontier funding and refuses to concede to Venn's advantages."},"rank":"I","branch":"Impulse","faction":"academy","role":{"es":"Aprendiz de frontera","en":"Frontier apprentice"}},{"id":16,"name":"Maro Gant","gender":{"es":"hombre","en":"man"},"age":19,"appearance":{"es":"Rizos castaños desordenados, ojos dorados y pecas. Chaqueta amarilla y negra, cuello acústico abierto como una flor de pétalos de membrana; grabador de carrete y bandas translúcidas con ondas sonoras. Eco: medición de ecos.","en":"Tousled brown curls, golden eyes and freckles; a yellow-and-black jacket, a flower-shaped acoustic collar and a reel recorder."},"bio":{"es":"Narrador entusiasta que evita responsabilidades. Discute ética periodística con Rita, su hermana.","en":"An enthusiastic storyteller who sometimes dodges responsibility. His flower-shaped sound collar and reel recorder follow him into arguments about journalism with his sister Rita."},"rank":"I","branch":"Echo","faction":"academy","role":{"es":"Documentalista en formación","en":"Documentary apprentice"}},{"id":17,"name":"Grit Fallow","gender":{"es":"mujer","en":"woman"},"age":24,"appearance":{"es":"Rizos rojo cobrizo hacia un lado, lateral rapado con marcas y ojos ámbar. Camisa marfil, capa burdeos y delantal de forja; cuatro brazos mecánicos auxiliares externos, además de sus dos brazos naturales, para herramientas y válvulas. Caldera: pisada pesada.","en":"Copper-red curls with a shaved side, amber eyes and a forge apron. Four external auxiliary arms complement her two natural arms."},"bio":{"es":"Capitana de tercer año. Quiere graduar a su equipo con seguridad; protege y cuestiona a Tessa.","en":"Protective, demanding and practical. Four external auxiliary arms help her work tools and valves. Getting her team safely to graduation matters more than looking invincible."},"rank":"III","branch":"Boiler","faction":"academy","role":{"es":"Capitana de tercer año","en":"Third-year captain"}},{"id":18,"name":"Vela Noll","gender":{"es":"mujer","en":"woman"},"age":25,"appearance":{"es":"Cabello miel en grandes tirabuzones espirales y ojos verdes. Ornamento de cabeza de porcelana y latón con brote tras vidrio; vestido verde y marfil, con estructura torácica de costillas cerámicas que protege tejidos y plantas vivas. Bastion: fortificación móvil.","en":"Large honey-blonde spiral curls, green eyes, a porcelain sprout ornament and a green-white dress with a living ceramic rib framework."},"bio":{"es":"Hermana de Berta. Firmó con una empresa para financiar su localidad y también persigue su carrera.","en":"A career, a corporate contract and a home village that needs infrastructure. Berta's older sister loves her family, but her ambitions do not disappear because they disagree."},"rank":"III","branch":"Bastion","faction":"academy","role":{"es":"Especialista en fortificación","en":"Fortification specialist"}},{"id":19,"name":"Niska Toll","gender":{"es":"mujer","en":"woman"},"age":23,"appearance":{"es":"Piel morena oscura, ondas largas platino y ojos azul hielo. Gran sombrero azul y marfil con abanico cerámico y perla; traje de placas claras y enorme escudo en espiral de concha o ammonite, de porcelana craquelada y juntas de latón. Bastion: escudo craquelado.","en":"Dark skin, long platinum waves and ice-blue eyes; a large blue-and-white fan hat and a cracked porcelain ammonite shield."},"bio":{"es":"Estudiante de Karst y sobrina de Bernt. Justa y orgullosa; quiere superar a Runa.","en":"Proud, fair and tired of accusations of favouritism. Bernt's niece carries a cracked porcelain spiral shield and intends to defeat Runa on her own merits."},"rank":"III","branch":"Bastion","faction":"academy","role":{"es":"Competidora de Karst","en":"Karst competitor"}},{"id":20,"name":"Pella Durn","gender":{"es":"mujer","en":"woman"},"age":24,"appearance":{"es":"Pelo corto negro con puntas rojas; visor de filigrana y mecanismo ocular. Sombrero burdeos con cintas de película, traje teatral rojo y negro, cilindro grabador en el antebrazo y dispositivo dorado en forma de ojo en la palma. Eco: espejo de grabación.","en":"Short black hair with red tips, a mechanical blindfold, a film-ribbon hat and a golden eye-shaped recording device in her palm."},"bio":{"es":"Edita el periódico escolar. Quiere exponer ayudas fraudulentas; debe contrastar datos y puede equivocarse.","en":"A film-ribbon hat, a mechanical blindfold and a golden recording eye in her palm. She investigates dubious funding, and knows that a compelling story still needs evidence."},"rank":"II","branch":"Echo","faction":"academy","role":{"es":"Editora del periódico","en":"School newspaper editor"}},{"id":21,"name":"Runa Bell","gender":{"es":"mujer","en":"woman"},"age":25,"appearance":{"es":"Trenza larga azul cobalto y ojos dorados. Auriculares mecánicos, chaqueta negra, marfil y naranja; gran martillo de engranajes y vidrio con núcleo verde visible. Su tamaño no aumenta por sí solo su licencia ni sus poderes. Caldera: circulación anular.","en":"A long cobalt-blue braid, golden eyes, mechanical headphones and a black-white-orange outfit; a huge glass-and-gear hammer with a visible green core."},"bio":{"es":"Campeona escolar, nivel IV. Busca dirigir rescates y está comprometida con Oren.","en":"A cobalt braid and a huge glass-and-gear hammer announce a seasoned competitor. She wants to lead rescue teams and has a life of her own with her fiancé Oren."},"rank":"IV","branch":"Boiler","faction":"academy","role":{"es":"Campeona de Vardam","en":"Vardam champion"}},{"id":22,"name":"Kora Senn","gender":{"es":"mujer","en":"woman"},"age":24,"appearance":{"es":"Piel gris lavanda, ojos dorados y rizos largos verde oscuro. Blusa marfil de mangas amplias, corpiño verde y faja coral; bastidor de ramas coralinas con globos de vidrio llenos de cultivos y grandes membranas con nervaduras. Trama: puentes simbióticos.","en":"Grey-lavender skin, long dark-green curls and golden eyes; coral frameworks, glass culture globes and broad veined membranes."},"bio":{"es":"Alumna de intercambio. Defiende derechos de los simbiontes y rechaza la asimilación forzada del Coro.","en":"An advocate for symbiont rights with coral frameworks and living membranes. Kora wants cooperation that leaves room for refusal, and does not speak for every member of her people."},"rank":"III","branch":"Weave","faction":"academy","role":{"es":"Estudiante de intercambio","en":"Exchange student"}},{"id":23,"name":"Lotte Harn","gender":{"es":"mujer","en":"woman"},"age":23,"appearance":{"es":"Dos grandes coletas rizadas rosa cobrizo y ojos turquesa. Gorra marfil con gafas y pequeños mecanismos de ala, monóculo de engranajes, conjunto petróleo, crema y burdeos; alas de membrana translúcida sobre soportes articulados. Enjambre: alas plegables.","en":"Large copper-pink curled ponytails, turquoise eyes, an ivory wing-trimmed cap and folding translucent membrane wings."},"bio":{"es":"Exhibicionista y responsable. Quiere fabricar aeronaves económicas; respeta a Neri y compite por patentes.","en":"Showy, capable and willing to take responsibility. Folding membrane wings are part of her dream of affordable aircraft. She respects Neri's craft and competes for the same patents."},"rank":"II","branch":"Swarm","faction":"academy","role":{"es":"Inventora de vuelo","en":"Flight inventor"}},{"id":24,"name":"Venn Strake","gender":{"es":"hombre","en":"man"},"age":24,"appearance":{"es":"Pelo negro ondulado y ojos grises, rostro serio. Chistera marfil con gran bocina de latón, placas acústicas en un lateral de cara y cuello, traje violeta oscuro y corbatón blanco; bastidor de membranas y disco sonoro. Eco: filo de silencio.","en":"Black waves, grey eyes, an ivory top hat with a brass horn, a dark-violet suit and asymmetric acoustic plating."},"bio":{"es":"Rival de Ulmar. Elegante y resentido; se opone a ser el anuncio de su familia.","en":"Elegant, resentful and determined to be more than his family's advertisement. A brass horn crowns his ivory top hat; losing a match will not erase his independence."},"rank":"III","branch":"Echo","faction":"academy","role":{"es":"Competidor de Ulmar","en":"Ulmar competitor"}},{"id":25,"name":"Oren Pike","gender":{"es":"hombre","en":"man"},"age":26,"appearance":{"es":"Piel morena, cabello oscuro corto, ojos ámbar, bigote y barba corta. Gorra con reloj y gafas, casaca verde con detalles rojos; tres grandes cilindros postales de vidrio con cartas enrolladas y sellos, unidos a un bastidor de tuberías. Impulso: salto de riel.","en":"Brown skin, short black hair and a trimmed beard; a clock cap, a green courier coat and three glass postal cylinders."},"bio":{"es":"Practicante avanzado y prometido de Runa. Tiene trabajo, horarios y afectos independientes.","en":"A clock cap, a green coat and three glass postal cylinders. Oren has routes to finish, colleagues to care about and a real engagement to Runa."},"rank":"III","branch":"Impulse","faction":"academy","role":{"es":"Mensajero de prácticas","en":"Apprentice courier"}},{"id":26,"name":"Torv Kass","gender":{"es":"hombre","en":"man"},"age":25,"appearance":{"es":"Pelo corto gris blanco, cuerpo fuerte y marcas en el rostro. Pieza filtrante de latón sobre la nariz que deja libre la boca; ropa de trabajo oscura y marfil, grandes costillas cerámicas articuladas y fibras vivas rojas y verdes visibles en el armazón. Bastion: capas desplazadas.","en":"Short grey-white hair, a scarred strong build and a brass nose filter. Layered ceramic ribs expose red and green living fibres."},"bio":{"es":"Luchador clandestino de armadura cerámica por capas. Quiere decidir sobre su propia vida; compartir un enemigo no basta para ganarse su confianza.","en":"Layered ceramic ribs protect a scarred fighter with a brass nose filter. Torv wants control over his own life, and a shared enemy is not enough to win his trust."},"rank":"III","branch":"Bastion","faction":"academy","role":{"es":"Luchador clandestino","en":"Underground fighter"}},{"id":27,"name":"Hesta Darg","gender":{"es":"mujer","en":"woman"},"age":56,"appearance":{"es":"Cabello gris y castaño recogido, facciones maduras y monóculo ámbar. Conjunto verde y marfil con cuello abovedado de seis pétalos; brazo mecánico con cápsula de vidrio y fibras verdes, y mano articulada de latón. Dirección de Vardam; dominio de presión de nivel IV.","en":"A mature face, pinned grey-brown hair, an amber monocle and a six-petal green-and-ivory collar; a glass-fibre mechanical arm."},"bio":{"es":"Dirige Vardam y defiende su autonomía. Su dominio de presión y su experiencia no la sitúan por encima de la responsabilidad por sus decisiones.","en":"A mature pressure specialist under a six-petal collar. Keeping the academy autonomous takes difficult choices, and her position does not place her beyond accountability."},"rank":"IV","branch":"Boiler","faction":"academy","role":{"es":"Directora de Vardam","en":"Vardam headmistress"}},{"id":28,"name":"Vessa Kurn","gender":{"es":"mujer","en":"woman"},"age":39,"appearance":{"es":"Coleta larga negra verdosa, sombrero marfil de ala oval y baja, máscara de pico blanco de punta aguda y lentes ámbar asimétricas. Abrigo marfil y petróleo, guantes oscuros, dos botellas dorsales de cultivos verdes y grandes fuelles de branquias. Trama: investigadora.","en":"A long black-green ponytail, a low ivory hat and a sharp ivory beak mask with asymmetric amber lenses; living culture bottles and gill bellows."},"bio":{"es":"Investigadora de simbiosis que insiste en el consentimiento informado. Su máscara de pico marfil, lentes ámbar y coleta negra verdosa son inconfundibles.","en":"A sharp ivory beak mask, amber lenses and a dark green ponytail. Vessa insists on informed consent and believes that opening old records matters more than empty apologies."},"rank":"IV","branch":"Weave","faction":"academy","role":{"es":"Investigadora de simbiosis","en":"Symbiosis researcher"}},{"id":29,"name":"Irena Holt","gender":{"es":"mujer","en":"woman"},"age":41,"appearance":{"es":"Piel morena, rizos cobrizos hacia un lado y otro lateral rapado. Reloj y pequeño cilindro luminoso en la mejilla, antebrazo mecanizado, hombrera semejante a una gran campana rota; abrigo de rescate azul, gris y naranja y equipo de cuerdas. Caldera: instrucción y evacuación.","en":"Brown skin, copper curls with a shaved side, a cheek clock, a mechanical forearm and a broken-bell shoulder guard."},"bio":{"es":"Su campo de presión anclado puede desviar impactos enormes o ayudar a mover escombros pesados. Necesita combustible y ventanas de ventilación. Exige retiradas seguras y quiere proteger a los heridos.","en":"Strict training, clear exits and a practical concern for the injured. Her anchored pressure field can redirect tremendous impacts, but fuel and venting still limit every rescue."},"rank":"V","branch":"Boiler","faction":"academy","role":{"es":"Instructora de rescate","en":"Rescue instructor"}},{"id":30,"name":"Marga Soot","gender":{"es":"mujer","en":"woman"},"age":48,"appearance":{"es":"Rizos grises cortos, cuerpo robusto y lleno, gafas sobre la cabeza. Camisa amarilla de mangas claras remangadas, peto azul y exoesqueleto externo de banco de trabajo con prensa y yunque. Sus brazos son naturales; sigue sin implantes. Ingeniera sin implantes.","en":"Short grey curls and a robust build; a yellow shirt, blue work apron and external workbench exoskeleton. Her arms are natural; she has no implants."},"bio":{"es":"Ingeniera sin implantes y con brazos naturales. Su potencia proviene de herramientas y un exoesqueleto externos de presión. Enseña a Edda a construir equipos reparables y defiende la formación obrera.","en":"Natural arms, no implants and an external workbench exoskeleton. Marga teaches Edda to build equipment that workers can actually repair, while fighting a patent dispute of her own."},"rank":"III","branch":"Boiler","faction":"academy","role":{"es":"Ingeniera de presión","en":"Pressure engineer"}},{"id":31,"name":"Neve Oss","gender":{"es":"mujer","en":"woman"},"age":34,"appearance":{"es":"Ondas largas negras con matiz violeta y ojos gris violeta. Implante púrpura y dorado junto al oído y la sien; sastrería azul y marfil, alto cuello acústico de paneles cerámicos y dispositivos de membranas de registro. Eco: archivo.","en":"Long black-violet waves, grey-violet eyes, purple-and-gold ear mechanisms and a high blue-and-ivory ceramic sound collar."},"bio":{"es":"Quiere registros verificables y privacidad. Su técnica no le permite conocer cualquier pasado.","en":"Evidence and privacy deserve equal care. Behind a blue-white acoustic collar, Neve works to make academy records verifiable. Her craft cannot reveal anyone's entire past."},"rank":"III","branch":"Echo","faction":"academy","role":{"es":"Archivera de Vardam","en":"Vardam archivist"}},{"id":32,"name":"Bernt Toll","gender":{"es":"hombre","en":"man"},"age":51,"appearance":{"es":"Calvo, barba gris y complexión fuerte y madura. Ropa azul y marfil, gran calibre semicircular graduado alrededor de los hombros y contrapeso pendular sobre el pecho; herramientas de medida de latón. Bastion: dirección de estudios.","en":"A bald head, grey beard and mature broad build; blue-and-ivory clothes, a semicircular measuring frame and a pendulum counterweight."},"bio":{"es":"Se toma en serio las normas y la equidad. Exige mucho a su sobrina Niska.","en":"A semicircular measuring frame and pendulum identify a serious defender of standards. He expects fairness from everyone, including his niece Niska."},"rank":"IV","branch":"Bastion","faction":"academy","role":{"es":"Director de estudios","en":"Academic director"}},{"id":33,"name":"Janus Reed","gender":{"es":"hombre","en":"man"},"age":44,"appearance":{"es":"Cabello castaño largo recogido y ojos grises. Máscara acústica marfil y latón sobre la parte inferior de cara y mandíbula, mecanismo de oído; traje violeta de cuello floral y disco de resonancia montado en un aro. Eco: docencia.","en":"Long brown hair tied back, grey eyes and an ivory-brass lower-face sound mask; a violet floral collar and a framed resonance disc."},"bio":{"es":"Docente de resonancia con máscara acústica sobre la mandíbula y cuello floral violeta. Su vida y su historia no terminan al salir del aula.","en":"An ivory lower-face sound mask and a violet floral collar accompany his lessons. Like the other teachers, Janus has a history beyond the lecture hall."},"rank":"IV","branch":"Echo","faction":"academy","role":{"es":"Docente de resonancia","en":"Resonance lecturer"}},{"id":34,"name":"Otho Bress","gender":{"es":"hombre","en":"man"},"age":62,"appearance":{"es":"Cabello blanco ondulado largo y barba blanca abundante, rostro anciano amable. Camisa de lino y tirantes, brazos y manos mecánicos con fibras vegetales verdes, y gran invernadero dorsal de vidrio con plantas y flores. Enjambre de nivel II.","en":"Long white curls, a white beard and an elderly face; mechanical arms with green living fibres and a large glass greenhouse pack."},"bio":{"es":"Recolector retirado que cuida plantas y sus horarios. Su experiencia es práctica.","en":"A retired field collector with white curls, a generous beard and living fibres inside mechanical arms. Plants need care, and their keeper has working hours too."},"rank":"II","branch":"Swarm","faction":"academy","role":{"es":"Cuidador del invernadero","en":"Greenhouse caretaker"}},{"id":35,"name":"Alda Mott","gender":{"es":"mujer","en":"woman"},"age":47,"appearance":{"es":"Cabello rubio largo, ojos violetas y cintas rojas en la parte posterior del peinado. Complexión voluptuosa como la referencia posterior: busto abundante, cintura marcada y caderas amplias. Conserva sus 47 años, la blusa marfil de mangas amplias, el vestido-delantal rojo, reloj de bolsillo y recipientes térmicos de comedor. Gestiona el comedor.","en":"Long blonde hair, violet eyes and red ribbons; a full bust, defined waist and broad hips beneath an ivory blouse and red canteen apron."},"bio":{"es":"Madre de Bram. Equilibra alimentación, presupuesto, amistades y descanso.","en":"Blonde hair, red-and-ivory clothes and a warm food jar. Bram's mother balances nutrition, budgets, friendship and rest. Feeding an academy is skilled work."},"rank":"I","branch":"None","faction":"rusk","role":{"es":"Responsable del comedor","en":"Canteen keeper"}},{"id":36,"name":"Rita Gant","gender":{"es":"mujer","en":"woman"},"age":28,"appearance":{"es":"Rizos castaños cortos y pecas. Gorra violeta con gafas y pluma de cobre, pañuelo rojo y hombreras de paneles como plumas índigo; equipo de telégrafo o grabación con carrete y membrana. Periodista.","en":"Short brown curls and freckles; a violet feathered cap, a red scarf, indigo shoulder panels and a reel telegraph."},"bio":{"es":"Hermana de Maro; investiga permisos de aire y protege fuentes, con plazos y errores propios.","en":"A feathered cap, a red scarf and a reel telegraph. Maro's older sister investigates air permits, protects sources and has deadlines that do not wait for adventures."},"rank":"I","branch":"None","faction":"rusk","role":{"es":"Periodista de Rusk","en":"Rusk journalist"}},{"id":37,"name":"Nell Sarga","gender":{"es":"mujer","en":"woman"},"age":33,"appearance":{"es":"Cabello rojo recogido y ojos ámbar. Respirador marfil sobre nariz y boca, uniforme de asistencia verde y blanco con emblema rojo; brazo y mano mecánicos con cámara de vidrio y fibras verdosas, mochila de viales y material de auxilio. Enfermera y sindicalista.","en":"Red hair in a bun, amber eyes and a white-green medical respirator; a glass-fibre mechanical arm and a pack of care supplies."},"bio":{"es":"Enfermera y sindicalista de Trama especializada en cuidados complejos de tejidos. Defiende las decisiones de sus pacientes, los horarios de cuidado y sus propias responsabilidades familiares.","en":"A white-green respirator and a glass-fibre mechanical arm accompany complex tissue care. Patients' choices, decent working hours and her own family all matter to Nell."},"rank":"III","branch":"Weave","faction":"academy","role":{"es":"Enfermera y sindicalista","en":"Nurse and organiser"}},{"id":38,"name":"Ysra Kelm","gender":{"es":"mujer","en":"woman"},"age":45,"appearance":{"es":"Piel oscura, cabello cobrizo muy largo con gruesas trenzas blancas entrelazadas. Chaqueta azul y marfil de capitana, gorra y gafas mecánicas; timón y linterna de cultivo o señal de vidrio. Conserva un rostro adulto de 45 años. Capitana de aeronave.","en":"Dark skin, long copper hair interwoven with thick white braids; a blue-and-ivory captain's coat, goggles and a living signal lamp."},"bio":{"es":"Tía de Odra. Prioriza tripulación, rutas y sustento; el transporte requiere tiempo y dinero.","en":"Copper hair threaded with white braids, a captain's coat and a living signal lamp. Odra's aunt puts her crew first. A safe passage still needs a schedule and payment."},"rank":"III","branch":"None","faction":"rusk","role":{"es":"Capitana de aeronave","en":"Airship captain"}},{"id":39,"name":"Ors Rook","gender":{"es":"hombre","en":"man"},"age":54,"appearance":{"es":"Cabello cobrizo entrecano, bigote y barba grises; mantiene la cojera establecida. Pieza de cobre enrollada junto al oído, una mano mecánica, camisa marfil remangada y delantal azul con ventana de horno y mandos de presión. Reparador.","en":"Grey-copper hair and beard, an established limp and one mechanical hand; a blue furnace-window apron with pressure controls."},"bio":{"es":"Reparador de Rusk y padre de Tessa. Trabaja con herramientas de presión pese a una antigua lesión industrial. Padre e hija discrepan sobre los riesgos y las deudas del taller.","en":"A grey-copper beard, a mechanical hand and a blue furnace apron. Tessa's father still runs his workshop after an industrial injury; father and daughter disagree about risk and debt."},"rank":"II","branch":"Boiler","faction":"rusk","role":{"es":"Reparador de Rusk","en":"Rusk repairer"}},{"id":40,"name":"Ferris Durn","gender":{"es":"hombre","en":"man"},"age":31,"appearance":{"es":"Pelo castaño oscuro revuelto y pequeña perilla. Gafas de inspección con una gran lente rectangular facetada, abrigo oscuro con marfil y mostaza, bastidor graduado; tarjetas, sello e instrumentos de verificación cuando trabaja. Inspector municipal.","en":"Tousled dark-brown hair and a small goatee; a faceted rectangular inspection lens, a dark ivory-mustard coat and a measuring frame."},"bio":{"es":"Hermano de Pella. Investiga sobornos de mantenimiento, exige pruebas y no encubre cualquier conducta de su hermana.","en":"A faceted inspection lens and a measuring frame accompany a stubborn respect for procedure. He investigates maintenance kickbacks and does not automatically excuse his sister Pella."},"rank":"I","branch":"None","faction":"rusk","role":{"es":"Inspector municipal","en":"Municipal inspector"}},{"id":41,"name":"Maud Voss","gender":{"es":"mujer","en":"woman"},"age":49,"appearance":{"es":"Recogido de rizos plateados con lila y engranajes, ojo mecánico dorado y placa facial. Traje negro y burdeos, cuello cortesano de grandes paneles con pequeñas válvulas, guantes o placas articuladas marfil en las manos. Bastion de capas urbanas.","en":"Pinned silver-lilac curls, a mechanical golden eye, a burgundy-black valve collar and articulated porcelain hand plates."},"bio":{"es":"Madre de Neri y directiva de Nueve Hornos. Cree que concentrar la propiedad mantiene estables las ciudades; sus decisiones afectan a muchas más personas que su familia.","en":"A mechanical eye, porcelain hand plates and a valve-lined collar. Neri's mother believes concentrated ownership keeps cities stable, a conviction with very real consequences."},"rank":"IV","branch":"Bastion","faction":"furnaces","role":{"es":"Directiva de Nueve Hornos","en":"Nine Furnaces executive"}},{"id":42,"name":"Jost Rask","gender":{"es":"hombre","en":"man"},"age":37,"appearance":{"es":"Pelo negro corto, cejas marcadas y pieza de latón en la mandíbula. Arnés oscuro y dorado de cierres contractuales, dos enormes carretes de documentos a la espalda y mecanismo de antebrazo con cámara de presión de vidrio. Caldera de cobro.","en":"Short black hair and a brass jaw piece; a dark-gold contract harness, two large document reels and a glass pressure forearm device."},"bio":{"es":"Ejecuta recuperaciones y es leal al contrato. Las pruebas y los intereses concretos pueden cambiar su posición.","en":"Two enormous document reels and a pressure arm travel with the man who carries out recovery orders. Jost is loyal to contracts, not to whichever hero happens to arrive."},"rank":"III","branch":"Boiler","faction":"furnaces","role":{"es":"Ejecutor de contratos","en":"Contract enforcer"}},{"id":43,"name":"Orla Quill","gender":{"es":"mujer","en":"woman"},"age":46,"appearance":{"es":"Ondas muy largas blancas y verde claro, ojos verdes y motivo ocular dorado sobre la frente. Ropa coral y marfil con cuello de grandes branquias florales, aro dorsal y membranas vegetales translúcidas. El motivo de la frente no concede clarividencia. Trama: dominio de coro.","en":"Very long white-green waves, green eyes and a golden forehead eye ornament; coral-white floral gills and a ring of living membranes."},"bio":{"es":"Una sanadora poderosa que detesta la enfermedad y la soledad. Qué significa salvar a alguien es la pregunta que atraviesa su fe y su trabajo.","en":"White-green hair and floral gills surround a powerful healer who truly hates illness and loneliness. What it means to save someone is the question at the heart of her faith."},"rank":"V","branch":"Weave","faction":"choir","role":{"es":"Voz del Coro","en":"Voice of the Choir"}},{"id":44,"name":"Sero Quill","gender":{"es":"hombre","en":"man"},"age":29,"appearance":{"es":"Cabello castaño claro ondulado y ojos grises, mecanismo rosado de cobre junto al oído. Ropa oliva y marfil, cuello de campanas, cámara de vidrio sobre el pecho y frascos dorsales de simbiontes mensajeros luminosos. Enjambre de comunicación.","en":"Light-brown curls, grey eyes and a copper ear mechanism; an ivory-olive outfit, a bell collar and glass jars of glowing messenger symbionts."},"bio":{"es":"Mensajero criado por la orden; Quill es apellido religioso, no parentesco automático. Su fe cambia por costes reales, no por amistad inmediata.","en":"A collar of little bells and glass jars of messenger symbionts. Sero has witnessed real acts of aid. Quill is a religious name, not proof of a blood relationship."},"rank":"III","branch":"Swarm","faction":"choir","role":{"es":"Mensajero del Coro","en":"Choir messenger"}},{"id":45,"name":"Garran Flint","gender":{"es":"hombre","en":"man"},"age":58,"appearance":{"es":"Cuerpo íntegramente mecánico de porcelana marfil y metal, rostro angular de autómata y ojos claros luminosos; sin pelo ni piel humanos visibles. Chistera blanca con engranajes, traje marfil y negro, corbatón, manos articuladas y arcos dorsales. Conserva identidad masculina y edad de 58; no se inventa el origen de su cuerpo. Armazón sin tejido vivo.","en":"An entirely mechanical ivory-porcelain and metal body, an angular face, luminous eyes, a white gear-trimmed top hat and articulated hands."},"bio":{"es":"Culpa a todas las tecnologías simbióticas de una catástrofe anterior. Su origen corporal no se inventa por su apariencia.","en":"An entirely mechanical body of ivory porcelain and metal beneath a gear-topped hat. Garran blames an old disaster on symbiotic technology and wants the world to change."},"rank":"V","branch":"Boiler","faction":"iron","role":{"es":"Dirigente del Hierro Puro","en":"Pure Iron leader"}},{"id":46,"name":"Vadra Kest","gender":{"es":"mujer","en":"woman"},"age":32,"appearance":{"es":"Cabello negro violáceo largo y un ojo ámbar visible. Máscara lisa de porcelana clara con línea roja central y abertura ocular, correa con pequeño reloj; traje blanco y violeta con rojo, mecanismos de antebrazo, bobinas y cables magnéticos. Cables magnéticos e inhibidores.","en":"Long black-violet hair and a visible amber eye; a white porcelain mask with a red stripe, white-violet hunting clothes and magnetic cable mechanisms."},"bio":{"es":"Prioriza la eficiencia. Dañar civiles tiene consecuencias políticas; ella no representa a todas las personas contrarias a los monopolios.","en":"A white porcelain mask with a red line, magnetic cables and inhibitors. Efficiency guides her methods, but damage to civilians cannot be wished away."},"rank":"IV","branch":"Impulse","faction":"iron","role":{"es":"Especialista en inhibición","en":"Inhibition specialist"}},{"id":47,"name":"Ethel Marr","gender":{"es":"mujer","en":"woman"},"age":43,"appearance":{"es":"Rizos violetas recogidos y ojos dorados; media máscara de porcelana craquelada que cubre un lado del rostro. Vestuario de laboratorio marfil y violeta, cajones de muestras y brazos auxiliares externos articulados que sostienen recipientes de cultivos. Trama: ensamblaje.","en":"Pinned violet curls, golden eyes and a cracked porcelain half-mask; ivory-violet laboratory clothes and delicate external specimen arms."},"bio":{"es":"Investigadora de cultivos y ensamblaje, con media máscara craquelada y brazos auxiliares externos. Su trayectoria se cruza con la de Vessa.","en":"A cracked half-mask, violet curls and delicate external arms surround her specimen work. Her professional history intersects with Vessa's, and old projects leave lasting responsibilities."},"rank":"V","branch":"Weave","faction":"cabinet","role":{"es":"Investigadora del Injerto","en":"Graft researcher"}},{"id":48,"name":"Paska Orrel","gender":{"es":"mujer","en":"woman"},"age":35,"appearance":{"es":"Piel morena, rizos cortos negros violáceos, ojos ámbar y dientes metálicos dorados. Sombrero de cuatro pétalos de loto translúcidos color ámbar, ropa dorada, verde y violeta; antebrazo mecánico con cultivo tras vidrio y maletines de muestras. Enjambre recolector.","en":"Brown skin, short black-violet curls, amber eyes and golden teeth; a translucent four-petal amber lotus hat and a glass culture forearm."},"bio":{"es":"Comerciante de muestras e intermediaria. Vende información, conserva salidas y no conoce todos los laboratorios.","en":"An amber four-petal lotus hat, golden teeth and a glass culture arm. Paska trades samples and information while making sure she always has a way out."},"rank":"II","branch":"Swarm","faction":"cabinet","role":{"es":"Comerciante de muestras","en":"Specimen broker"}},{"id":49,"name":"Nema Wry","gender":{"es":"mujer","en":"woman"},"age":38,"appearance":{"es":"Trenza larga cobriza, gran sombrero naval azul y burdeos con reloj. Pequeña pieza mecánica en la mejilla, abrigo azul de mando y brazo mecánico con cilindro de vidrio rojo anaranjado y mano articulada. Caldera de riel.","en":"A long copper braid, a clock-trimmed naval hat and a blue command coat; a mechanical arm with a red-orange glass pressure cylinder."},"bio":{"es":"Protege su comunidad móvil y cobra peajes extorsivos. Puede convertirse en aliada o adversaria según los hechos.","en":"A copper braid, a clock-trimmed naval hat and a red-orange pressure arm. She protects a moving community and charges a price for passage. Alliance depends on what actually happens."},"rank":"IV","branch":"Boiler","faction":"rail","role":{"es":"Capitana del Último Riel","en":"Last Rail captain"}},{"id":50,"name":"Huld Penn","gender":{"es":"mujer","en":"woman"},"age":30,"appearance":{"es":"Cabello blanco corto ondulado y ojos turquesa. Uniforme marfil y verde azulado, grandes paneles prismáticos articulados; ambos brazos de vidrio con fibras y plantas verdes en el interior y manos mecánicas. Bastion de refracción.","en":"Short white waves and turquoise eyes; an ivory-teal uniform, articulated prism panels and two mechanical glass arms filled with green fibres."},"bio":{"es":"Capitana de la guardia ferroviaria, leal a los residentes; se opone a sacrificar pasajeros por Nema.","en":"Short white curls, turquoise eyes and two glass arms filled with green fibres. Huld is loyal to the train's residents, even when that means contradicting Nema."},"rank":"III","branch":"Bastion","faction":"rail","role":{"es":"Capitana de la guardia","en":"Rail guard captain"}},{"id":51,"name":"Rovel Sorn","gender":{"es":"hombre","en":"man"},"age":61,"appearance":{"es":"Pelo plateado con zonas oscuras y arrugas de 61 años; visor negro opaco con engranaje lateral. Traje blanco y negro con gran cuello de campana invertida, carretes de bandas de registro y una mano mecánica oscura. Eco de secuencias.","en":"Silver-black hair, an aged face, a black opaque visor and an inverted-bell collar; recording reels and a dark mechanical hand."},"bio":{"es":"Custodia registros y busca respuestas al problema de la guerra. Sus archivos y su idea del orden plantean preguntas difíciles.","en":"A black visor and an inverted-bell collar frame an ageing archivist. Rovel sees order as an answer to war, but the records he guards leave difficult questions."},"rank":"V","branch":"Echo","faction":"chamber","role":{"es":"Custodio de registros","en":"Keeper of records"}},{"id":52,"name":"Sivra Pell","gender":{"es":"mujer","en":"woman"},"age":27,"appearance":{"es":"Ondas hasta los hombros negras violáceas y plateadas, ojos violetas. Pequeña placa clara junto a la mandíbula y pieza óptica junto a un ojo; traje púrpura, grandes paneles de espejo plegados y brazo mecánico con cilindro violeta y mano articulada. Eco de muestreo.","en":"Silver-black-violet shoulder-length waves and violet eyes; a cheek plate, folding mirror panels and a purple-lit mechanical arm."},"bio":{"es":"Obtiene fragmentos al tocar registros y dispositivos concretos. Su técnica exige contacto y no permite leer pensamientos ni apropiarse de cualquier recuerdo.","en":"Violet mirrors and a purple-lit mechanical arm support her work with recorded fragments. Contact with specific devices is necessary; another person's mind is never an open book."},"rank":"III","branch":"Echo","faction":"chamber","role":{"es":"Especialista en muestreo","en":"Record sampling specialist"}}],"disciplines":[{"id":"Boiler","es":"Caldera","en":"Boiler","symbol":"boiler","color":"#bb653f","desc":{"es":"Calor, vapor, compresión y propulsión. La fuerza empieza en una cámara que puede soportarla.","en":"Heat, steam, compression and propulsion. Power begins with a chamber that can contain it."},"cost":{"es":"Combustible · temperatura · resistencia del armazón","en":"Fuel · temperature · frame strength"},"example":{"es":"Una línea de soldadura, un salto por chorro o un campo de rescate que desvía impactos.","en":"A welding line, a jet-assisted leap or an anchored rescue field that redirects impacts."}},{"id":"Weave","es":"Trama","en":"Weave","symbol":"weave","color":"#6f7d48","desc":{"es":"Fibras, tendones, adhesión, construcción orgánica y reparación de tejidos.","en":"Fibres, tendons, adhesion, organic construction and tissue repair."},"cost":{"es":"Biomasa · metabolismo · reservas · especialización","en":"Biomass · metabolism · reserves · specialisation"},"example":{"es":"Desde suturas hasta órganos reconstruidos. Una Firma de regeneración especializada de rango V puede sostener una supervivencia casi imposible durante un tiempo limitado.","en":"From sutures to reconstructed organs. A specialised rank V regeneration Signature can sustain near-impossible survival for a limited time."}},{"id":"Bastion","es":"Bastion","en":"Bastion","symbol":"bastion","color":"#557e88","desc":{"es":"Caparazones, soportes minerales, placas y estructuras cerámicas articuladas.","en":"Shells, mineral supports, plating and articulated ceramic structures."},"cost":{"es":"Peso · articulaciones · fragilidad · conducción térmica","en":"Weight · joints · brittleness · heat conduction"},"example":{"es":"Un escudo plegable puede ser tan decisivo para un rescate como para un duelo.","en":"A folding shield can be as decisive in a rescue as in a duel."}},{"id":"Swarm","es":"Enjambre","en":"Swarm","symbol":"swarm","color":"#aa844a","desc":{"es":"Organismos auxiliares y unidades coordinadas para explorar, transportar o intervenir.","en":"Auxiliary organisms and coordinated units for scouting, transport and intervention."},"cost":{"es":"Número · alcance · alimento · carga de mando","en":"Numbers · range · food · command load"},"example":{"es":"Escarabajos de carga, polillas luminosas o alas de membrana. Edda demuestra que el sistema puede ser completamente externo.","en":"Cargo beetles, luminous moths or membrane wings. Edda shows that the whole system can remain external."}},{"id":"Impulse","es":"Impulso","en":"Impulse","symbol":"impulse","color":"#6689a3","desc":{"es":"Bioelectricidad, reacción, conducción nerviosa y mecanismos magnéticos.","en":"Bioelectricity, reaction, neural conduction and magnetic mechanisms."},"cost":{"es":"Conductores · interferencia · sobrecarga","en":"Conductors · interference · overload"},"example":{"es":"Rutas de conducción, velocidad asistida, cables magnéticos e inhibidores.","en":"Conductive routes, assisted speed, magnetic cables and inhibitors."}},{"id":"Echo","es":"Eco","en":"Echo","symbol":"echo","color":"#8e6b91","desc":{"es":"Vibración, sonido, percepción de ritmos y engaños sensoriales locales.","en":"Vibration, sound, rhythm sensing and local sensory misdirection."},"cost":{"es":"Medio · alcance · ruido · registros disponibles","en":"Medium · range · noise · available records"},"example":{"es":"Grabar una voz o recuperar un fragmento exige un medio. Una grabación no equivale a una mente ni a un alma.","en":"Recording a voice or recovering a fragment requires a medium. A recording is not a mind or a soul."}}],"ranks":[{"id":"I","name":"Ignition","label":{"es":"Ignición","en":"Ignition"},"desc":{"es":"Capacidad básica y equipo ligero. No presupone implantes ni una Firma.","en":"Baseline capacity and light equipment. Implants or a Signature are not assumed."}},{"id":"II","name":"Circuit","label":{"es":"Circuito","en":"Circuit"},"desc":{"es":"Salida sostenida y combinaciones fundamentales.","en":"Sustained output and fundamental combinations."}},{"id":"III","name":"Assembly","label":{"es":"Ensamble","en":"Assembly"},"desc":{"es":"Técnicas complejas y coordinación de varias etapas.","en":"Complex techniques and multi-stage coordination."}},{"id":"IV","name":"Crucible","label":{"es":"Crisol","en":"Crucible"},"desc":{"es":"Firma madura y dominio local dentro de su especialidad.","en":"A mature Signature and local control within a specialisation."}},{"id":"V","name":"Colossus","label":{"es":"Coloso","en":"Colossus"},"desc":{"es":"Potencia enorme o transformación cualitativa de la rama.","en":"Enormous output or a qualitative transformation within a branch."}},{"id":"VI","name":"Crown","label":{"es":"Corona","en":"Crown"},"desc":{"es":"Capacidad y precisión excepcionales, con condiciones y costes reales.","en":"Exceptional capacity and precision, with real conditions and costs."}}],"regions":[{"id":"rusk","name":"Rusk","title":{"es":"La ciudad que respira","en":"The breathing city"},"desc":{"es":"Ciudad escalonada de rieles elevados, invernaderos y barrios de humo. Vardam se alza entre puentes y torres de fuelles. El aire limpio, las reparaciones y los permisos forman parte de la vida diaria.","en":"A terraced city of elevated rails, greenhouses and smoky districts. Vardam rises between bridges and bellows towers. Clean air, repairs and permits are part of daily life."},"tags":{"es":"Rieles · talleres · vida de academia","en":"Rails · workshops · academy life"}},{"id":"sarga","name":"Sarga","title":{"es":"Bajo el bosque de hongos","en":"Beneath the mushroom forest"},"desc":{"es":"Humedales de hongos gigantes, raíces de vidrio, aldeas elevadas y estaciones sumergidas. La cooperación entre especies convive con la contaminación y las disputas por la recolección.","en":"Wetlands of giant fungi, glass roots, stilt villages and submerged stations. Cooperation between species coexists with pollution and disputes over harvesting."},"tags":{"es":"Micelio · recolección · simbiosis","en":"Mycelium · harvesting · symbiosis"}},{"id":"orrel","name":"Orrel","title":{"es":"Donde el óxido canta","en":"Where rust sings"},"desc":{"es":"Llanuras salinas y arcos de hierro hueco, cruzados por carros mineros de vela. Antiguos campos de batalla y comunidades con escasez de agua requieren algo más que fuerza.","en":"Salt plains and hollow iron arches crossed by sail-driven mining carts. Old battlefields and water-starved settlements demand more than strength."},"tags":{"es":"Sal · viento · viejas guerras","en":"Salt · wind · old wars"}},{"id":"kelm","name":"Kelm","title":{"es":"El mar también está vivo","en":"The sea is alive too"},"desc":{"es":"Archipiélagos de puertos flotantes, diques de coral óseo, torres de corrientes cálidas y ciudades sumergidas. Navegar exige atención al clima, a las criaturas y a la tripulación.","en":"Archipelagos of floating ports, coral-bone docks, warm-current towers and submerged cities. Navigation demands attention to weather, creatures and crew."},"tags":{"es":"Navegación · arrecifes · aeronaves","en":"Navigation · reefs · airships"}},{"id":"marn","name":"Marn","title":{"es":"Fuego bajo las montañas","en":"Fire beneath the mountains"},"desc":{"es":"Minas en terrazas, hornos y ciudades de forja. Los intereses de obreros, comercio y frontera chocan en lugares donde fabricar y mantener son labores esenciales.","en":"Terraced mines, furnaces and forge cities. Workers, merchants and frontier interests collide where manufacture and maintenance are essential work."},"tags":{"es":"Minería · forja · trabajo","en":"Mining · forging · labour"}},{"id":"elda","name":"Elda","title":{"es":"Un silencio entre conductos","en":"Silence between the conduits"},"desc":{"es":"Un abismo de cortinas de tubos, arcos semejantes a costillas y espejos de agua. Las ruinas contienen sistemas antiguos que requieren investigación y preparación para acercarse.","en":"An abyss of hanging conduits, rib-like arches and reflecting water. Its ruins hold ancient systems that demand investigation and preparation before approaching."},"tags":{"es":"Ruinas · profundidad · sistemas antiguos","en":"Ruins · depth · ancient systems"}}],"factions":[{"id":"furnaces","name":{"es":"Nueve Hornos","en":"Nine Furnaces"},"title":{"es":"Propiedad y mantenimiento","en":"Ownership and maintenance"},"desc":{"es":"Controla licencias de núcleos, instalaciones de aire y materiales. Sus servicios sostienen ciudades; la dependencia que generan también concentra poder.","en":"Controls core licences, air infrastructure and materials. Its services sustain cities; the dependency they create also concentrates power."},"people":"Maud Voss · Jost Rask"},{"id":"choir","name":{"es":"Coro de la Carne Nueva","en":"Choir of New Flesh"},"title":{"es":"Nadie debería sufrir a solas","en":"No one should suffer alone"},"desc":{"es":"Nació como una red de ayuda y tratamientos simbióticos que salvó vidas. En su interior se discute hasta dónde puede llegar una unión antes de borrar a quienes la componen.","en":"Began as a mutual-aid network whose symbiotic treatments saved lives. Within it, people disagree about how far a union can go before erasing its members."},"people":"Orla Quill · Sero Quill"},{"id":"iron","name":{"es":"Liga del Hierro Puro","en":"Pure Iron League"},"title":{"es":"La promesa de independencia","en":"The promise of independence"},"desc":{"es":"Una corriente radical de rechazo a la dependencia empresarial y biológica. Sus métodos y su visión de los cuerpos modificados la enfrentan a otras comunidades.","en":"A radical rejection of corporate and biological dependency. Its methods and views on modified bodies bring it into conflict with other communities."},"people":"Garran Flint · Vadra Kest"},{"id":"cabinet","name":{"es":"Gabinete del Injerto","en":"Graft Cabinet"},"title":{"es":"La vida como proyecto","en":"Life as a project"},"desc":{"es":"Una red de laboratorios, muestras y armazones hechos por encargo. Investigar sus contratos y la procedencia de sus materiales exige reunir pruebas verificables.","en":"A network of laboratories, specimens and commissioned frames. Investigating its contracts and the origin of its materials requires verifiable evidence."},"people":"Ethel Marr · Paska Orrel"},{"id":"rail","name":{"es":"Compañía del Último Riel","en":"Last Rail Company"},"title":{"es":"Una ciudad en movimiento","en":"A city in motion"},"desc":{"es":"Da protección, transporte y rutas a una comunidad móvil. La seguridad, los peajes y las necesidades de pasajeros y residentes no siempre coinciden.","en":"Provides protection, transport and routes for a moving community. Security, tolls and the needs of passengers and residents do not always align."},"people":"Nema Wry · Huld Penn"},{"id":"chamber","name":{"es":"Cámara Ciega","en":"Blind Chamber"},"title":{"es":"Quién conserva la historia","en":"Who keeps history"},"desc":{"es":"Trabaja entre archivos, permisos e interpretaciones del pasado. Sus agentes disponen de información valiosa, aunque ninguna organización conoce todas las respuestas.","en":"Works among archives, permits and interpretations of the past. Its agents hold valuable information, but no organisation has every answer."},"people":"Rovel Sorn · Sivra Pell"}],"creatures":[{"name":"Copper Deer","rank":"I","type":"fauna","label":{"es":"Ciervo de cobre","en":"Copper Deer"},"desc":{"es":"Generalmente herbívoro. Defiende a sus crías; acercarse no garantiza un encuentro pacífico.","en":"Usually herbivorous. It defends its young; approaching does not guarantee a peaceful encounter."}},{"name":"Valve Leeches","rank":"I","type":"fauna","label":{"es":"Sanguijuelas de válvula","en":"Valve Leeches"},"desc":{"es":"Consumen películas de aceite y sellos. Un daño pequeño en una junta puede convertirse en un problema de mantenimiento.","en":"Feed on oil films and seals. Small damage to a joint can become a maintenance problem."}},{"name":"Glass Nests","rank":"I","type":"flora","label":{"es":"Nidos de vidrio","en":"Glass Nests"},"desc":{"es":"Colonias cristalinas aprovechables como material. La extracción altera su entorno y requiere un origen legítimo.","en":"Crystalline colonies that can provide material. Harvesting affects their surroundings and requires a legitimate source."}},{"name":"Memory Orchids","rank":"I","type":"flora","label":{"es":"Orquídeas de memoria","en":"Memory Orchids"},"desc":{"es":"Reproducen vibraciones cercanas. Su eco no conserva almas ni una historia ilimitada del lugar.","en":"Reproduce nearby vibrations. Their echoes preserve neither souls nor an unlimited history of a place."}},{"name":"Lantern Moths","rank":"I","type":"fauna","label":{"es":"Polillas farol","en":"Lantern Moths"},"desc":{"es":"Suelen ser inofensivas. Sus señales de luz también pueden revelar una posición.","en":"Usually harmless. Their light signals can also reveal a position."}},{"name":"Nurse Needles","rank":"I","type":"construct","label":{"es":"Agujas de asistencia","en":"Nurse Needles"},"desc":{"es":"Unidades de mantenimiento que pueden ayudar en un rescate o ser utilizadas de forma dañina.","en":"Maintenance units that can help with a rescue or be put to harmful use."}},{"name":"Porcelain Mutes","rank":"I","type":"sapient","label":{"es":"Mudos de porcelana","en":"Porcelain Mutes"},"desc":{"es":"Seres con identidad propia que se comunican mediante gestos. Su apariencia no los convierte en presas.","en":"Beings with their own identities who communicate through gestures. Their appearance does not make them prey."}},{"name":"Soot Wolves","rank":"II","type":"fauna","label":{"es":"Lobos de hollín","en":"Soot Wolves"},"desc":{"es":"Rastrean calor y rastros de humo. Comprender qué siguen puede evitar una persecución.","en":"Track heat and traces of smoke. Understanding what they follow may prevent a pursuit."}},{"name":"Rivet Mantises","rank":"II","type":"fauna","label":{"es":"Mantis de remaches","en":"Rivet Mantises"},"desc":{"es":"Detectan vibraciones del suelo. Sus articulaciones son un punto vulnerable que debe observarse en el terreno.","en":"Detect ground vibrations. Their joints are a vulnerable point to observe in the field."}},{"name":"Spore Spindles","rank":"II","type":"flora","label":{"es":"Husos de esporas","en":"Spore Spindles"},"desc":{"es":"Se dispersan con el viento y se activan según la humedad. Las condiciones ambientales importan.","en":"Disperse on the wind and activate according to humidity. Environmental conditions matter."}},{"name":"Lung Corals","rank":"II","type":"flora","label":{"es":"Corales pulmón","en":"Lung Corals"},"desc":{"es":"Filtran partículas del humo, aunque su crecimiento también puede obstruir conductos.","en":"Filter smoke particles, though their growth can also obstruct conduits."}},{"name":"Chain Ivy","rank":"II","type":"flora","label":{"es":"Hiedra de cadenas","en":"Chain Ivy"},"desc":{"es":"Se enrolla alrededor de fuentes de calor. Una máquina caliente puede atraer más atención que una persona.","en":"Coils around heat sources. A hot machine can attract more attention than a person."}},{"name":"Rust Roses","rank":"II","type":"flora","label":{"es":"Rosas de óxido","en":"Rust Roses"},"desc":{"es":"Absorben contaminación y acumulan toxinas. Cuidar un ecosistema exige tener en cuenta ambos efectos.","en":"Absorb pollution and accumulate toxins. Caring for an ecosystem means considering both effects."}},{"name":"Mist Sirens","rank":"II","type":"fauna","label":{"es":"Sirenas de niebla","en":"Mist Sirens"},"desc":{"es":"Cefalópodos flotantes capaces de imitar sonidos. La voz que escuchas quizá no proceda de una persona.","en":"Floating cephalopods capable of mimicking sounds. A voice you hear may not come from a person."}},{"name":"Census Hounds","rank":"II","type":"construct","label":{"es":"Sabuesos de censo","en":"Census Hounds"},"desc":{"es":"Siguen marcas de licencia. Sus criterios de rastreo pertenecen a un sistema, no a una idea del bien o el mal.","en":"Follow licence markers. Their tracking criteria belong to a system, not an idea of good and evil."}},{"name":"White Harvesters","rank":"II","type":"sapient","label":{"es":"Cosechadores blancos","en":"White Harvesters"},"desc":{"es":"Antiguos trabajadores y cuerpos agrícolas abandonados. Sus historias y decisiones merecen ser investigadas.","en":"Abandoned agricultural workers and bodies. Their histories and choices deserve investigation."}},{"name":"Unbound","rank":"II","type":"sapient","label":{"es":"Desvinculados","en":"Unbound"},"desc":{"es":"Han escapado de contratos neurales. Cada individuo posee nombre, decisiones y necesidades propias.","en":"Have escaped neural contracts. Every individual has a name, choices and needs of their own."}},{"name":"Boiler Bears","rank":"III","type":"fauna","label":{"es":"Osos de caldera","en":"Boiler Bears"},"desc":{"es":"Muy territoriales. La descarga de presión presenta señales observables antes de producirse.","en":"Highly territorial. A pressure discharge has observable signs before it occurs."}},{"name":"Siphon Trees","rank":"III","type":"flora","label":{"es":"Árboles sifón","en":"Siphon Trees"},"desc":{"es":"Compiten por el agua del subsuelo. La amenaza puede estar en los efectos sobre una comunidad y no en una persecución.","en":"Compete for groundwater. The threat may lie in effects on a community rather than a chase."}},{"name":"Cloud Rays","rank":"III","type":"fauna","label":{"es":"Rayas de nube","en":"Cloud Rays"},"desc":{"es":"Siguen las corrientes cálidas. Su ecología influye en la navegación y en las rutas aéreas.","en":"Follow warm air currents. Their ecology affects navigation and air routes."}},{"name":"Rail Centipedes","rank":"III","type":"fauna","label":{"es":"Ciempiés de riel","en":"Rail Centipedes"},"desc":{"es":"Utilizan vías y estructuras ferroviarias para aproximarse y atacar. El terreno determina las opciones.","en":"Use tracks and railway structures to approach and strike. Terrain determines the options."}},{"name":"Hollow Knights","rank":"III","type":"construct","label":{"es":"Caballeros huecos","en":"Hollow Knights"},"desc":{"es":"Armaduras vacías dirigidas a distancia. El operador necesita líneas de conexión.","en":"Empty armour directed remotely. Its operator requires connection lines."}},{"name":"Mycelial Wardens","rank":"III","type":"sapient","label":{"es":"Guardianes miceliales","en":"Mycelial Wardens"},"desc":{"es":"Custodian los bosques fúngicos y discrepan entre sí. Hablar con uno no equivale a hablar con todos.","en":"Guard fungal forests and disagree with one another. Speaking to one does not mean speaking to all."}},{"name":"Ballast Whales","rank":"IV","type":"fauna","label":{"es":"Ballenas de lastre","en":"Ballast Whales"},"desc":{"es":"Grandes seres marinos. Proteger una ruta no obliga a exterminar a los animales que la cruzan.","en":"Large marine creatures. Protecting a route does not require exterminating the animals that cross it."}},{"name":"Bronze Widow","rank":"IV","type":"singular","label":{"es":"Viuda de bronce","en":"Bronze Widow"},"desc":{"es":"Una enorme mantis de una guerra antigua que permanece en los salares. Entidad singular.","en":"An enormous mantis left by an old war in the salt plains. A unique entity."}},{"name":"Rust Bride","rank":"IV","type":"singular","label":{"es":"Novia de óxido","en":"Rust Bride"},"desc":{"es":"Una comunidad vegetal consciente afectada por la contaminación. Sanar el entorno y combatir no son siempre la misma tarea.","en":"A conscious plant community affected by pollution. Healing an environment and fighting are not always the same task."}},{"name":"Hollow Saint","rank":"V","type":"singular","label":{"es":"Santo hueco","en":"Hollow Saint"},"desc":{"es":"Un cuerpo de combate coral vinculado al Coro de la Carne Nueva. Requiere preparación y conocimiento de su funcionamiento.","en":"A choral battle-body linked to the Choir of New Flesh. Preparation and knowledge of its workings are essential."}},{"name":"Dike Leviathan","rank":"V","type":"singular","label":{"es":"Leviatán del dique","en":"Dike Leviathan"},"desc":{"es":"Una criatura colosal capaz de afectar al embalse. Observar, desviar el agua y rescatar también son objetivos válidos.","en":"A colossal creature that can affect the reservoir. Observation, diverting water and rescue are also valid objectives."}},{"name":"Dreaming Train","rank":"V","type":"singular","label":{"es":"Tren soñador","en":"Dreaming Train"},"desc":{"es":"El núcleo vivo autónomo de la ciudad ferroviaria. Su identidad no equivale a la de todos sus pasajeros.","en":"The autonomous living core of the rail city. Its identity is not the identity of all its passengers."}},{"name":"Matrix Zero","rank":"VI","type":"singular","label":{"es":"Matriz Cero","en":"Matrix Zero"},"desc":{"es":"Un antiguo centro de regulación bajo Elda, ligado a varias ciudades. Los registros disponibles no explican todavía toda su historia.","en":"An ancient regulating centre beneath Elda, linked to several cities. Available records do not yet explain its entire history."}},{"name":"Unidentified record","rank":"?","type":"singular","label":{"es":"Registro sin identificar","en":"Unidentified record"},"desc":{"es":"Una estructura sin soldaduras. Un ritmo demasiado lento para ser una máquina corriente. El expediente continúa en el Archivo Reservado.","en":"A seamless structure. A rhythm too slow for an ordinary machine. The record continues in the Reserved Archive."}}]};
